using namespace dtc_l1;
#ifndef GLOBAL_IDLE
#define GLOBAL_IDLE 0
#endif
struct Env {
 config cfg;oo_frontend f;uint64_t cycle=1;bool reserve;unsigned reserved=0;
 struct Reg{unsigned need=0,next=0;};std::map<uint64_t,Reg> regs;
 Env(unsigned sets=64,unsigned ways=8,unsigned physical=640,bool use_reserve=false):cfg(make(sets,ways,physical)),f(cfg),reserve(use_reserve){}
 static config make(unsigned sets,unsigned ways,unsigned physical){config c;c.selected_mode=mode::PAPER_OO;c.finite_service=true;c.progressive_wakeup=false;c.tag_hash_bankrow=true;c.logical_sets=sets;c.logical_ways=ways;c.physical_lines=physical;c.oo_pib_entries=128;c.ref_count_bits=13;c.tag_banks=4;c.tag_requests_per_bank_per_cycle=1;c.tag_requests_per_cycle=4;c.allocation_width=4;return c;}
 bool admit(uint64_t uid,unsigned need=1){assert(need<=32&&(!reserve||need>0));if(regs.count(uid)){assert(regs[uid].need==need);return true;}if(reserve&&reserved+need>cfg.physical_lines)return false;if(!f.admit(uid))return false;regs[uid]={need,0};reserved+=reserve?need:0;return true;}
 io_access_result access(uint64_t uid,uint64_t address){if(reserve)assert(regs.at(uid).next<regs.at(uid).need);f.advance_service(cycle);assert(f.try_serve_tag(cycle,address));auto result=f.access(cycle++,uid,address);if(result.kind!=io_access_kind::NO_FREE_LINE&&regs[uid].next<regs[uid].need)++regs[uid].next;return result;}
 void complete(physical_identity id){f.complete(id);}
 void drain(unsigned n=800){for(unsigned j=0;j<n;++j)f.advance_service(cycle++);}
 bool retire(uint64_t uid){auto i=regs.find(uid);assert(i!=regs.end());if(i->second.next!=i->second.need||!f.entry_ready_for(uid))return false;bool ok=f.retire_ready_uid(cycle++,uid);if(ok){reserved-=reserve?i->second.need:0;regs.erase(i);}return ok;}
 physical_identity one(uint64_t uid,uint64_t address){assert(admit(uid));auto r=access(uid,address);assert(r.kind==io_access_kind::NEW_MISS);complete(r.physical);drain(8);assert(retire(uid));return r.physical;}
 unsigned visible()const{return std::count_if(f.m_tags.begin(),f.m_tags.end(),[](auto &t){return t.valid;});}
};
void emit(const std::string &name,const std::string &classification,const std::string &extra=""){std::cout<<"{\"case\":\""<<name<<"\",\"header\":\""<<(GLOBAL_IDLE?"GLOBAL_IDLE_LRU_V2_CPU":"ORIGINAL_9EED")<<"\",\"classification\":\""<<classification<<"\",\"PASS\":true"<<extra<<"}\n";}
uint64_t find_address(unsigned sets,unsigned target,uint64_t begin=0){for(uint64_t x=begin;;++x)if(logical_tag_set(x*128,sets,true)==target)return x*128;}
void idle_trap(unsigned sets,unsigned ways){Env e(sets,ways);for(unsigned i=0;i<640;++i)e.one(i+1,uint64_t(i)*128);assert(e.f.occupancy()==0&&e.f.allocated_lines()==640);assert(e.admit(10001));unsigned failed=0;for(unsigned j=0;j<16;++j){auto r=e.access(10001,640ULL*128);if(r.kind==io_access_kind::NO_FREE_LINE)++failed;else{assert(GLOBAL_IDLE&&r.kind==io_access_kind::NEW_MISS);e.complete(r.physical);e.drain();assert(e.retire(10001));break;}}assert(failed==(GLOBAL_IDLE?0:16));emit("idle_ref0_fullpool_"+std::to_string(sets)+"x"+std::to_string(ways),GLOBAL_IDLE?"GLOBAL_IDLE_RECYCLE_PROGRESS":"RECLAIMABLE_REF0_NO_PROGRESS",",\"prior_completed_retired\":640,\"old_live_refs\":0,\"NO_FREE_repeats\":"+std::to_string(failed));}
void local_victim_progress(){Env e(64,16);std::set<uint64_t> used;uint64_t addr=0;for(unsigned i=0;i<16;++i){addr=find_address(64,0,i?addr/128+1:0);used.insert(addr);e.one(i+1,addr);}uint64_t cursor=0;for(unsigned i=16;i<640;++i){while(used.count(cursor*128)||logical_tag_set(cursor*128,64,true)==0)++cursor;used.insert(cursor*128);e.one(i+1,cursor++*128);}assert(e.f.allocated_lines()==640);auto fresh=find_address(64,0,addr/128+1);assert(!used.count(fresh));assert(e.admit(10001));auto r=e.access(10001,fresh);assert(r.kind==io_access_kind::NEW_MISS);emit("target_fullset_ready_ref0_victim","EXISTING_LOCAL_VICTIM_PROGRESS");}
void shapes512(unsigned sets,unsigned ways){Env e(sets,ways);for(unsigned i=0;i<2048;++i)e.one(i+1,uint64_t(i)*128);assert(e.visible()<=512&&e.f.allocated_lines()<=512);assert(e.admit(9999));auto r=e.access(9999,2047ULL*128);assert(r.kind==io_access_kind::VALID_HIT);assert(e.retire(9999));emit("shape512_"+std::to_string(sets)+"x"+std::to_string(ways),"CPU_DIRECTED_PROGRESS_NOT_UNIVERSAL_PROOF",",\"completed_requests\":2048,\"visible_Tag_max\":512");}
void refs_and_duplicate_address(){Env e;assert(e.admit(1));auto a=e.access(1,0);assert(e.admit(2));auto b=e.access(2,0);auto c=e.access(2,0);assert(a.kind==io_access_kind::NEW_MISS&&b.kind==io_access_kind::PENDING_HIT&&c.kind==io_access_kind::PENDING_HIT);assert(a.physical.id==b.physical.id&&a.physical.generation==b.physical.generation);assert(e.f.ref_count(a.physical)==2);assert(e.f.m_phys[a.physical.id].waiters.size()==2);e.complete(a.physical);e.drain();assert(e.retire(1)&&e.f.ref_count(a.physical)==1);assert(e.retire(2)&&e.f.ref_count(a.physical)==0);emit("multiple_refs_repeated_address_dedup_fill_once","REF_WAITER_IDENTITY_CONSERVED");}
void partial_guard(){Env e;assert(e.admit(1,3));auto a=e.access(1,0);e.complete(a.physical);e.drain();assert(e.f.entry_ready_for(1));assert(!e.retire(1));auto b=e.access(1,128),c=e.access(1,256);e.complete(b.physical);e.complete(c.physical);e.drain();assert(e.retire(1));emit("PIB_partially_registered_retirement_filter","ACTUAL_NEXT_REFERENCE_GATE_REQUIRED",",\"header_ready_was_not_integrated_retirable\":true");}
void pending_full_and_release(){Env e(4,4,4);std::vector<physical_identity> refs;for(unsigned i=0;i<4;++i){assert(e.admit(i+1));auto r=e.access(i+1,i*128);refs.push_back(r.physical);}assert(e.admit(5));auto blocked=e.access(5,512);assert(blocked.kind==io_access_kind::NO_FREE_LINE);e.complete(refs[0]);e.drain();blocked=e.access(5,512);assert(blocked.kind==io_access_kind::NO_FREE_LINE);assert(e.retire(1));auto after=e.access(5,512);assert((after.kind==io_access_kind::NEW_MISS)==bool(GLOBAL_IDLE));emit("pending_return_fullpool_liveRef_not_reclaimed",GLOBAL_IDLE?"FAIR_RETURN_RETIRE_THEN_IDLE_PROGRESS":"LIVE_BLOCK_THEN_IDLE_CROSSSET_GAP",",\"ready_ref1_not_reclaimed\":true");}
void replacement_generation(){Env e(4,1,2);assert(e.admit(1));auto a=e.access(1,0);assert(e.admit(2));auto b=e.access(2,512);assert(a.physical.id!=b.physical.id&&!e.f.tag_visible(a.physical));e.complete(a.physical);e.drain();assert(e.f.entry_ready_for(1)&&!e.f.entry_ready_for(2));assert(e.retire(1));assert(!e.f.is_allocated(a.physical));assert(e.admit(3));auto c=e.access(3,1024);assert(c.physical.id==a.physical.id&&c.physical.generation>a.physical.generation);assert(!e.f.fill_identity_matches(a.physical));e.complete(c.physical);e.complete(b.physical);e.drain();assert(e.retire(2)&&e.retire(3));emit("Tag_replacement_pending_physical_generation_reuse","EXACT_GENERATION_AND_OWNER_WAKEUP_PRESERVED");}
void fair_live_temporary(){Env e(64,8);std::vector<physical_identity> refs;for(unsigned u=0;u<128;++u){assert(e.admit(u+1,u?5:6));for(unsigned j=0;j<5;++j){auto r=e.access(u+1,uint64_t(u*5+j)*128);assert(r.kind==io_access_kind::NEW_MISS);refs.push_back(r.physical);}}auto blocked=e.access(1,640ULL*128);assert(blocked.kind==io_access_kind::NO_FREE_LINE);for(auto id:refs)e.complete(id);e.drain(1000);assert(!e.retire(1));assert(e.retire(2));auto progress=e.access(1,640ULL*128);assert(progress.kind==io_access_kind::NEW_MISS);emit("one_partial_plus_complete_entries_fullpool","LEGAL_LIVE_TEMPORARY_WITH_FAIR_RETURN_AND_RETIRE");}
void adversarial_multi_partial(unsigned sets,unsigned ways){Env e(sets,ways);std::vector<physical_identity> refs;for(unsigned u=0;u<128;++u){assert(e.admit(u+1,6));for(unsigned j=0;j<5;++j){auto r=e.access(u+1,uint64_t(u*5+j)*128);assert(r.kind==io_access_kind::NEW_MISS);refs.push_back(r.physical);}}for(auto id:refs)e.complete(id);e.drain(1000);unsigned retired=0;for(unsigned u=1;u<=128;++u)retired+=e.retire(u);assert(retired==0);assert(e.access(1,640ULL*128).kind==io_access_kind::NO_FREE_LINE);emit("adversarial_128partial_API_"+std::to_string(sets)+"x"+std::to_string(ways),"API_ONLY_LIVE_PARTIAL_CYCLE_HOLD",",\"production_reachability_not_proven\":true,\"all_returned_but_no_fully_registered_entry\":true");}
void reservation(){Env e(64,16,640,true);std::vector<physical_identity> refs;for(unsigned u=1;u<=20;++u)assert(e.admit(u,32));assert(!e.admit(21,32)&&e.reserved==640);for(unsigned u=1;u<=20;++u)for(unsigned j=0;j<32;++j){auto r=e.access(u,uint64_t((u-1)*32+j)*128);assert(r.kind==io_access_kind::NEW_MISS);refs.push_back(r.physical);}for(auto id:refs)e.complete(id);e.drain(1200);assert(e.retire(1)&&e.reserved==608);assert(e.admit(21,32));auto r=e.access(21,640ULL*128);assert((r.kind==io_access_kind::NEW_MISS)==bool(GLOBAL_IDLE));emit("known32_reference_budget_20_of128_slots",GLOBAL_IDLE?"RESERVATION_PLUS_GLOBAL_IDLE_PROGRESS":"RESERVATION_ALONE_DOES_NOT_FIX_CROSSSET_IDLE_TRAP",",\"admitted_before_token_limit\":20,\"raw_PIB_capacity\":128,\"token_limit\":640");}
void pib_capacity(){Env e;for(unsigned i=0;i<128;++i)assert(e.admit(i+1));assert(!e.admit(129));auto a=e.access(1,0);e.complete(a.physical);e.drain();assert(e.retire(1));assert(e.admit(129));emit("PIB_partial_occupancy_and_slot_reuse","PIB128_ADMISSION_AND_REUSE_VALIDATED");}
void quota_global(){if(!GLOBAL_IDLE)return;Env e(4,4,4);for(unsigned i=0;i<4;++i)e.one(i+1,i*128);assert(e.admit(5)&&e.admit(6));auto cycle=e.cycle;auto first=e.f.access(cycle,5,512);assert(first.kind==io_access_kind::NEW_MISS);auto second=e.f.access(cycle,6,640);assert(second.kind==io_access_kind::NO_FREE_LINE);auto next=e.f.access(cycle+1,6,640);assert(next.kind==io_access_kind::NEW_MISS);emit("cross_reclaim_quota_one_per_cycle","SERVICE_QUOTA_BACKPRESSURE_NOT_STRUCTURAL_FAILURE");}
void pending_queue_defense(){
#if GLOBAL_IDLE
 Env e(4,4,4);std::vector<physical_identity> old;for(unsigned i=0;i<4;++i)old.push_back(e.one(i+1,i*128));
 // Fault-injected transient queue marker tests the explicit guard, not a claim
 // this ready/ref0+pending state arises under the original healthy lifecycle.
 e.f.m_service_returns.push_back({old[0],UINT64_MAX,0});assert(e.f.reclaim_one_idle_tag(e.cycle));assert(e.f.is_allocated(old[0]));assert(e.f.tag_visible(old[0]));assert(!e.f.is_allocated(old[1]));e.f.m_service_returns.clear();e.f.assert_shadow_refs();emit("fault_injected_pending_generation_excluded_from_global_victim","PENDING_RETURN_GUARD_DEFENSE_NOT_PRODUCTION_REACHABILITY");
#endif
}
void reservation_idempotent(){Env e(64,16,640,true);assert(e.admit(1,32));assert(e.admit(1,32));assert(e.reserved==32&&e.f.occupancy()==1);emit("reservation_repeated_UID_no_double_charge","RESERVATION_CONSERVATION");}
void expect_abort(const char *name,const std::function<void()> &action){pid_t p=fork();assert(p>=0);if(!p){struct rlimit z{0,0};setrlimit(RLIMIT_CORE,&z);assert(freopen("/dev/null","w",stderr)!=nullptr);action();_exit(0);}int status=0;assert(waitpid(p,&status,0)==p);assert(WIFSIGNALED(status)&&WTERMSIG(status)==SIGABRT);emit(name,"EXPECTED_ASSERTION_PROTECTS_LIFECYCLE");}
int main(){
 idle_trap(64,16);idle_trap(128,8);local_victim_progress();shapes512(128,4);shapes512(32,16);refs_and_duplicate_address();partial_guard();pending_full_and_release();replacement_generation();fair_live_temporary();adversarial_multi_partial(64,8);adversarial_multi_partial(128,4);adversarial_multi_partial(32,16);reservation();pib_capacity();quota_global();pending_queue_defense();reservation_idempotent();
 expect_abort("reservation_rejects_more_than32_refs",[]{Env e(64,16,640,true);e.admit(1,33);});
 expect_abort("no_release_live_reference",[]{Env e;assert(e.admit(1));auto r=e.access(1,0);e.f.release(r.physical);});
 expect_abort("no_duplicate_return_pending",[]{Env e;assert(e.admit(1));auto r=e.access(1,0);e.complete(r.physical);e.complete(r.physical);});
 expect_abort("no_stale_generation_fill",[]{Env e(4,1,2);assert(e.admit(1));auto a=e.access(1,0);assert(e.admit(2));auto b=e.access(2,512);e.complete(a.physical);e.drain();assert(e.retire(1));assert(e.admit(3));auto c=e.access(3,1024);assert(c.physical.id==a.physical.id);e.complete(a.physical);});
 expect_abort("no_double_release",[]{Env e(4,1,2);assert(e.admit(1));auto a=e.access(1,0);assert(e.admit(2));e.access(2,512);e.complete(a.physical);e.drain();assert(e.retire(1));e.f.release(a.physical);});
 expect_abort("no_stale_PIB_waiter_slot_wakeup",[]{Env e;assert(e.admit(1));auto a=e.access(1,0);++e.f.m_phys[a.physical.id].waiters[0].slot_generation;e.complete(a.physical);e.drain();});
}
